 * dately — zero-dependency ESM date utilities.
 *
 * DST strategy: calendar arithmetic operates on a "UTC noon anchor".
 * A Date's local calendar fields (year/month/day) can shift when you add
 * wall-clock time across a DST transition (e.g. adding 24 hours on a
 * 23-hour day lands on the same wall clock time next day). To avoid this,
 * we lift the date's *calendar fields* into UTC at noon — noon is safe
 * because no timezone has an offset that moves 12:00 UTC out of the same
 * civil day (offsets are within ±14h) — do whole-day math there where
 * every day is exactly 86,400 seconds, and convert back only at the end.
 */

const MS_PER_DAY = 86_400_000;

/** Clone `date` with its local calendar fields re-anchored to UTC noon. */
function toNoonAnchor(date) {
  return new Date(
    Date.UTC(date.getFullYear(), date.getMonth(), date.getDate(), 12),
  );
}

/**
 * Add `days` calendar days to `date`, preserving the local time-of-day.
 * DST-safe: the day math happens on a UTC noon anchor, so a 23- or
 * 25-hour local day cannot cause an off-by-one.
 */
export function addDays(date, days) {
  const anchored = toNoonAnchor(date);
  anchored.setUTCDate(anchored.getUTCDate() + days);
  // Rebuild from the anchored fields so the original wall-clock time of
  // day is preserved through any DST transition.
  return new Date(
    anchored.getUTCFullYear(),
    anchored.getUTCMonth(),
    anchored.getUTCDate(),
    date.getHours(),
    date.getMinutes(),
    date.getSeconds(),
    date.getMilliseconds(),
  );
}

/**
 * Return a new Date set to midnight (local) of the week containing `date`.
 * `weekStartsOn`: 0 = Sunday (default), 1 = Monday, ..., 6 = Saturday.
 */
export function startOfWeek(date, { weekStartsOn = 0 } = {}) {
  if (!Number.isInteger(weekStartsOn) || weekStartsOn < 0 || weekStartsOn > 6) {
    throw new RangeError(`weekStartsOn must be an integer 0..6, got ${weekStartsOn}`);
  }
  const result = new Date(
    date.getFullYear(),
    date.getMonth(),
    date.getDate(),
  );
  const diff = (result.getDay() - weekStartsOn + 7) % 7;
  result.setDate(result.getDate() - diff);
  return result;
}

/** True when both dates fall on the same local calendar day. */
export function isSameDay(a, b) {
  return (
    a.getFullYear() === b.getFullYear() &&
    a.getMonth() === b.getMonth() &&
    a.getDate() === b.getDate()
  );
}

/**
 * Whole number of calendar days between two local dates (b - a).
 *
 * Why the UTC noon anchor makes this DST-safe: comparing raw timestamps
 * divides by elapsed *absolute* time, so a DST transition (23- or 25-hour
 * day) would round the result up or down incorrectly. Instead we take
 * each date's civil y/m/d, place it at 12:00 UTC — a fixed offset from
 * midnight that no real timezone's shift can push across a day boundary —
 * and difference those. Since both anchors share the same instant-of-day,
 * their difference is always an exact multiple of 86,400,000 ms, giving
 * the true count of calendar-day boundaries crossed regardless of TZ.
 */
export function differenceInCalendarDays(a, b) {
  return Math.round((toNoonAnchor(b) - toNoonAnchor(a)) / MS_PER_DAY);
}

/** Format as `yyyy-mm-dd` using local calendar fields. */
export function formatISODate(date) {
  const y = String(date.getFullYear()).padStart(4, '0');
  const m = String(date.getMonth() + 1).padStart(2, '0');
  const d = String(date.getDate()).padStart(2, '0');
  return `${y}-${m}-${d}`;
}

// Days-per-month for a non-leap year; February is adjusted below.
const DAYS_IN_MONTH = [31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31];

function isLeapYear(year) {
  return (year % 4 === 0 && year % 100 !== 0) || year % 400 === 0;
}

/**
 * Parse a strict `yyyy-mm-dd` string into a local-midnight Date, or null.
 *
 * Beyond the regex, real calendar validity is verified: the month must be
 * 1..12 and the day must exist in that month for that year (leap rules
 * included), so e.g. `2024-02-30`, `2023-02-29`, and `2024-13-01` are all
 * rejected rather than silently rolled over by the Date constructor.
 */
export function parseISODate(str) {
  if (typeof str !== 'string') return null;
  const match = /^(\d{4})-(\d{2})-(\d{2})$/.exec(str);
  if (!match) return null;

  const year = Number(match[1]);
  const month = Number(match[2]);
  const day = Number(match[3]);

  if (month < 1 || month > 12) return null;
  const maxDay =
    month === 2 && isLeapYear(year) ? 29 : DAYS_IN_MONTH[month - 1];
  if (day < 1 || day > maxDay) return null;

  return new Date(year, month - 1, day);
}
"})
