result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "/workspace/dately/test.mjs", "content": "// TZ must be set before any Date is constructed, hence before the import
// below resolves and runs module code.
process.env.TZ = 'America/New_York';

import test from 'node:test';
import assert from 'node:assert/strict';

import {
  addDays,
  startOfWeek,
  isSameDay,
  differenceInCalendarDays,
  formatISODate,
  parseISODate,
} from './index.mjs';

test('addDays handles month rollover', () => {
  const d = new Date(2024, 0, 31); // Jan 31 -> Feb 29 (leap year)
  assert.equal(formatISODate(addDays(d, 1)), '2024-02-01');
  assert.equal(formatISODate(addDays(new Date(2023, 0, 31), 1)), '2023-02-01');
});

test('addDays handles year rollover', () => {
  const d = new Date(2023, 11, 31);
  assert.equal(formatISODate(addDays(d, 1)), '2024-01-01');
  assert.equal(formatISODate(addDays(d, -1)), '2023-12-30');
});

test('startOfWeek with weekStartsOn 1 (Monday) vs 0 (Sunday)', () => {
  // 2024-01-10 was a Wednesday.
  const wednesday = new Date(2024, 0, 10);

  const mondayStart = startOfWeek(wednesday, { weekStartsOn: 1 });
  assert.equal(mondayStart.getDay(), 1);
  assert.equal(formatISODate(mondayStart), '2024-01-08');

  const sundayStart = startOfWeek(wednesday); // default 0
  assert.equal(sundayStart.getDay(), 0);
  assert.equal(formatISODate(sundayStart), '2024-01-07');

  // A Sunday itself is its own start under weekStartsOn 0...
  assert.equal(
    formatISODate(startOfWeek(new Date(2024, 0, 7), { weekStartsOn: 0 })),
    '2024-01-07',
  );
  // ...but rolls back a week under weekStartsOn 1.
  assert.equal(
    formatISODate(startOfWeek(new Date(2024, 0, 7), { weekStartsOn: 1 })),
    '2024-01-01',
  );

  assert.throws(() => startOfWeek(wednesday, { weekStartsOn: 7 }), RangeError);
});

test('isSameDay', () => {
  assert.ok(isSameDay(new Date(2024, 5, 1, 0, 0), new Date(2024, 5, 1, 23, 59)));
  assert.ok(!isSameDay(new Date(2024, 5, 1, 23, 59), new Date(2024, 5, 2, 0, 0)));
});

test('differenceInCalendarDays is DST-safe across the US spring-forward boundary', () => {
  // In America/New_York, 2024-03-10 is a 23-hour day (02:00 -> 03:00 EST->EDT).
  // Raw timestamp differencing across this gap yields 23h, which would round
  // to 0 days instead of 1 calendar day; noon anchoring stays exact.
  const before = parseISODate('2024-03-09'); // EST (UTC-5)
  const after = parseISODate('2024-03-10'); // EDT (UTC-4)
  assert.equal(after.getTime() - before.getTime(), 23 * 3_600_000);

  assert.equal(differenceInCalendarDays(before, after), 1);
  assert.equal(differenceInCalendarDays(after, before), -1);

  // Longer span straddling the transition is still exact.
  assert.equal(differenceInCalendarDays(parseISODate('2024-03-01'), parseISODate('2024-03-15')), 14);
});

test('differenceInCalendarDays across the fall-back boundary and month/year edges', () => {
  // 2024-11-03 is a 25-hour day in New York (EDT->EST).
  const before = parseISODate('2024-11-02');
  const after = parseISODate('2024-11-03');
  assert.equal(after.getTime() - before.getTime(), 25 * 3_600_000);
  assert.equal(differenceInCalendarDays(before, after), 1);

  assert.equal(differenceInCalendarDays(parseISODate('2024-12-31'), parseISODate('2025-01-01')), 1);
  assert.equal(differenceInCalendarDays(parseISODate('2024-01-31'), parseISODate('2024-02-01')), 1);
});

test('formatISODate zero-pads fields', () => {
  assert.equal(formatISODate(new Date(2024, 2, 5)), '2024-03-05');
  assert.equal(formatISODate(new Date(999, 0, 1)), '0999-01-01');
});

const invalidParseInputs = [
  ['2024-02-30', "Feb 30 doesn't exist"],
  ['2023-02-29', 'non-leap year Feb 29'],
  ['2100-02-29', 'century non-leap year (divisible by 100)'],
  ['2000-02-30', 'valid leap year but day out of range'],
  ['2024-13-01', 'month > 12'],
  ['2024-00-10', 'month < 1'],
  ['2024-04-31', 'April has 30 days'],
  ['2024-1-01', 'not zero-padded month'],
  ['20240101', 'missing dashes'],
  ['2024/01/01', 'wrong separator'],
  ['2024-01-01T00:00:00', 'full ISO datetime rejected'],
  ['', 'empty string'],
  ['  2024-01-01', 'leading whitespace'],
];

for (const [input, why] of invalidParseInputs) {
  test(`parseISODate rejects ${JSON.stringify(input)} (${why})`, () => {
    assert.equal(parseISODate(input), null);
  });
}

test('parseISODate accepts valid dates including leap-day edge cases', () => {
  assert.equal(formatISODate(parseISODate('2024-02-29')), '2024-02-29');
  assert.equal(formatISODate(parseISODate('2000-02-29')), '2000-02-29'); // div by 400
  assert.equal(formatISODate(parseISODate('1999-12-31')), '1999-12-31');
  assert.equal(formatISODate(parseISODate('0000-01-01')), '0000-01-01');
  assert.equal(parseISODate(null), null);
  assert.equal(parseISODate(undefined), null);
});
"})
